var classifierService = new TicketClassifierService(builder.Environment);
classifierService.TrainAndEvaluate();
builder.Services.AddSingleton(classifierService);

// Register thread-safe pooled prediction engine
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(classifierService.GetModelPath());

